public sealed class Book
{
    private readonly Lazy<Author> _author;
    public Book(long authorId, IAuthorGateway gw) =>
        _author = new Lazy<Author>(() => gw.Find(authorId));
    public Author Author => _author.Value;   // first read queries
}

public class Book
{
    public long Id { get; set; }
    public long AuthorId { get; set; }
    public virtual Author Author { get; set; } = null!;   // lazy proxy
}
